[归一化后的问题]
六月起各 SKU 的 GMV 分别是多少？

[已审查的查询计划]
{
  "assets": [
    {
      "asset": "order_paid",
      "join_key": null
    }
  ],
  "blocking_issues": [],
  "dimensions": [
    "sku"
  ],
  "filters": [
    "pay_time >= '2026-06-01'（六月起，起点为 2026-06-01 00:00:00）",
    "pay_status = 'paid'",
    "refund_status <> 'refunded'",
    "is_test_order = false"
  ],
  "grain": "sku（order_paid.sku_id，最小销售单元）",
  "limit": 1000,
  "metrics": [
    {
      "caliber": "SUM(order_paid.pay_amount)；按支付完成时间 pay_time 统计；含运费；剔除全额退款订单（refund_status <> 'refunded'）；剔除测试单（is_test_order = false）；仅 pay_status = 'paid'。不扣减部分退款。",
      "name": "gmv"
    }
  ],
  "order_by": [
    "gmv DESC"
  ],
  "output_columns": [
    "sku_id",
    "gmv"
  ],
  "time_range": {
    "end": null,
    "start": "2026-06-01"
  }
}

